-- Dungeon plans for the run leader (.bot run), exported by turtle-agent (plan-export). Plan format v1; the mapping is
-- docs/guides/dungeon-run-leader.md ("From plan v1 to rows"). The plan file in turtle-agent is the single source: edit it
-- there and export again, never these rows by hand. The plan row carries the unit lists cc_priority, cc_always and kill_first
-- (columns from 20261015200000_world.sql). Never edit this file once applied; export a new one.
--
-- Idempotent: each plan's rows are deleted, then inserted. The tables come from 20261014150000_world.sql.

-- hateforge_quarry: map 808, 6 legs, 416 steps
DELETE FROM `ai_dungeon_step` WHERE `plan` = 'hateforge_quarry';
DELETE FROM `ai_dungeon_leg` WHERE `plan` = 'hateforge_quarry';
DELETE FROM `ai_dungeon_plan` WHERE `plan` = 'hateforge_quarry';

-- The map-808 boss rows (ai_dungeon_boss, the pattern of 20261021114931_world.sql). The exporter does not write this table; the
-- five rows are the plan's boss entries, all rank 1 in creature_template, entry-scoped so another plan of map 808 would keep its own.
DELETE FROM `ai_dungeon_boss` WHERE `map` IN (808) AND `entry` IN (60735, 60829, 60737, 60736, 60734);
